const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  function getInfoAsync(obj) {
    return new Promise((resolve, reject) => obj.getInfo(resolve, reject));
  }

  // 1. Geometry & Time Definitions
  // North Crimean Canal segment (Nova Kakhovka -> north Crimea) buffered to capture surrounding cropland
  const canalLine = ee.Geometry.LineString([
    [33.350, 46.800],  // near Nova Kakhovka
    [33.990, 45.500]   // toward north Crimea
  ]);
  const roi = canalLine.buffer(15000); // 15 km buffer

  function dateWindow(centerStr, halfDays) {
    const c = new Date(centerStr + 'T00:00:00Z');
    const start = new Date(c); start.setUTCDate(start.getUTCDate() - halfDays);
    const end = new Date(c); end.setUTCDate(end.getUTCDate() + halfDays + 1); // end exclusive
    const s = start.toISOString().slice(0, 10);
    const e = end.toISOString().slice(0, 10);
    return { start: s, end: e, widthDays: halfDays * 2 + 1 };
  }

  // 2. Data Acquisition & Masking
  function maskS2sr(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000).copyProperties(image, image.propertyNames());
  }
  function getS2Col(start, end, geom) {
    return ee.ImageCollection('COPERNICUS/S2_SR')
      .filterDate(start, end)
      .filterBounds(geom)
      .map(maskS2sr)
      .select(['B4', 'B8']);
  }

  function applyScaleL2(image) {
    const optical = image.select(['SR_B.']).multiply(0.0000275).add(-0.2);
    return image.addBands(optical, null, true);
  }
  function maskLandsatL2(image) {
    const qa = image.select('QA_PIXEL');
    const mask = qa.bitwiseAnd(1 << 3).eq(0) // cloud
      .and(qa.bitwiseAnd(1 << 4).eq(0))     // cloud shadow
      .and(qa.bitwiseAnd(1 << 2).eq(0))     // cirrus
      .and(qa.bitwiseAnd(1 << 5).eq(0));    // snow
    return image.updateMask(mask);
  }
  function getLandsatCol(start, end, geom) {
    const l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').filterDate(start, end).filterBounds(geom);
    const l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2').filterDate(start, end).filterBounds(geom);
    return l8.merge(l9).map(applyScaleL2).map(maskLandsatL2).select(['SR_B4', 'SR_B5'], ['B4', 'B8']);
  }

  function compositeNDVI(col) {
    const img = col.median();
    return img.normalizedDifference(['B8', 'B4']).rename('NDVI');
  }

  async function analyzeAtDate(centerStr) {
    // Try S2 ±7 days, then S2 ±14 days, then Landsat ±14 days
    let attempt = [
      { src: 'S2', win: dateWindow(centerStr, 7) },
      { src: 'S2', win: dateWindow(centerStr, 14) },
      { src: 'Landsat', win: dateWindow(centerStr, 14) }
    ];
    for (let a of attempt) {
      let col = (a.src === 'S2')
        ? getS2Col(a.win.start, a.win.end, roi)
        : getLandsatCol(a.win.start, a.win.end, roi);
      const n = await getInfoAsync(col.size());
      if (n === 0) continue; // try next attempt
      const ndvi = compositeNDVI(col);
      // Pixel counts and mean
      const dictCount = await getInfoAsync(ndvi.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: roi,
        scale: 1000,
        maxPixels: 1e9
      }));
      const validCount = dictCount ? dictCount.NDVI || 0 : 0;
      const totalDict = await getInfoAsync(ee.Image(1).rename('const').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: roi,
        scale: 1000,
        maxPixels: 1e9
      }));
      const totalCount = totalDict ? totalDict.const || 0 : 0;
      const meanDict = await getInfoAsync(ndvi.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: roi,
        scale: 1000,
        maxPixels: 1e9
      }));
      const mean = meanDict ? meanDict.NDVI : null;
      return {
        src: a.src,
        imgs: n,
        windowDays: a.win.widthDays,
        valid: validCount,
        total: totalCount,
        mean: mean
      };
    }
    return { src: 'None', imgs: 0, windowDays: 0, valid: 0, total: 0, mean: null };
  }

  try {
    const areaKm2 = await getInfoAsync(roi.area().divide(1e6));
    console.log(`AOI area (km²): ${areaKm2 ? areaKm2.toFixed(0) : 'NA'}`);

    const t1 = '2023-06-03';
    const t2 = '2023-07-19';

    const s1 = await analyzeAtDate(t1);
    const s2 = await analyzeAtDate(t2);

    // Case 1: Empty collection(s)
    if (s1.imgs === 0 || s2.imgs === 0) {
      console.log(`Jun3 Images: ${s1.imgs} (src=${s1.src})`);
      console.log(`Jul19 Images: ${s2.imgs} (src=${s2.src})`);
      console.log('C1');
      return;
    }

    // Print concise stats
    const v1pct = (s1.total > 0) ? (100 * s1.valid / s1.total) : 0;
    const v2pct = (s2.total > 0) ? (100 * s2.valid / s2.total) : 0;
    console.log(`Jun3 src=${s1.src} imgs=${s1.imgs} windowDays=${s1.windowDays} valid%=${v1pct.toFixed(1)} meanNDVI=${s1.mean === null ? 'null' : s1.mean.toFixed(3)}`);
    console.log(`Jul19 src=${s2.src} imgs=${s2.imgs} windowDays=${s2.windowDays} valid%=${v2pct.toFixed(1)} meanNDVI=${s2.mean === null ? 'null' : s2.mean.toFixed(3)}`);

    // Case 2: No valid pixels
    if (s1.valid === 0 || s2.valid === 0) {
      console.log('C2');
      return;
    }

    // Case 3: Calculation failure (null/NaN/out-of-range)
    const invalid = (s1.mean === null || s2.mean === null ||
                     !isFinite(s1.mean) || !isFinite(s2.mean) ||
                     Math.abs(s1.mean) > 1.0 || Math.abs(s2.mean) > 1.0);
    if (invalid) {
      console.log('C3');
      return;
    }

    const delta = s2.mean - s1.mean; // Jul - Jun
    console.log(`NDVI Δ (Jul - Jun): ${delta.toFixed(3)}`);

    const browner = delta < -0.02; // decrease threshold
    console.log(`Browner? ${browner ? 'Yes' : 'No'}`);

    // Final Answer Tag
    console.log(browner ? 'A' : 'B');
  } catch (err) {
    // Unexpected error (collection/band names, syntax, memory, etc.)
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
